	"""User-entered descriptive text."""
	Overridden = ("Overridden", str, FieldPriority.OPTIONAL)
	"""YES if this object is being overridden by an enabled Model Result Override object."""
	Selected = ("Selected", str, FieldPriority.OPTIONAL)
	"""YES or NO field which displays if record has been selected.  The field can be used in combination with numerous script commands in auxiliary files.  Is also used to help choose records in the user interface sometimes"""
	Single = ("Single", float, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Delay in seconds for the input of Model Expression X into the Model Plane.  This is ignored during steady-state analysis."""
	Single__1 = ("Single:1", float, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Delay in seconds for the input of Model Expression Y into the Model Plane.  This is ignored during steady-state analysis."""
	Single__2 = ("Single:2", float, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Maximum value on the x-axis that defines the Inside Region.  This point corresponds to Ypt."""
	Single__3 = ("Single:3", float, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Point on the x-axis that defines the Inside Region.  This point corresponds to Ymax."""
	Single__4 = ("Single:4", float, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Maximum value on the y-axis that defines the Inside Region.  This point corresponds to Xpt."""
	Single__5 = ("Single:5", float, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Point on the y-axis that defines the Inside Region.  This point corresponds to Xmax."""
	Single__6 = ("Single:6", float, FieldPriority.OPTIONAL)
	"""Value of Model Expression X."""
	Single__7 = ("Single:7", float, FieldPriority.OPTIONAL)
	"""Value of Model Expression Y."""
	String = ("String", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""If YES, an operating point on the inside of the Inside Region will result in Meets Criteria = YES.  If NO, an operating point on the inside of the Inside Region will result in Meets Criteria = NO."""
	String__1 = ("String:1", str, FieldPriority.OPTIONAL)
	"""If not blank indicates any error associated with the definition of the model plane."""
	String__2 = ("String:2", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Set to YES so that the Inside Region is defined solely between the origin, Xmax, Xpt, Ymax, and Ypt.  Set to NO to extend the Inside Region to all other quadrants being bounded by Xmax, Ymax, and infinity.  """
	TSValidationString = ("TSValidationString", str, FieldPriority.OPTIONAL)
	"""When including remedial actions as part of transient stability analysis, this indicates how the model plane will be evaluated during the transient stability analysis."""

	ObjectString = 'ModelPlane'


