class ScheduledActions_Options(GObject):
	IncludeNormallyOpen = ("IncludeNormallyOpen", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""When using the Open Breakers action, Disconnects that are Closed but Normally Open will be opened in addition to Breakers.  When using Close Breakers actions, Disconnects that are Open but Normally Closed will be closed in addition to Breakers.    """
	SAAnimation = ("SAAnimation", float, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Hold time between animated increments"""
	SAAnimationUnits = ("SAAnimationUnits", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Units of the hold time between animated increments"""
	SAApplyActions = ("SAApplyActions", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Apply relevant scheduled actions by time."""
	SAApplyWindow = ("SAApplyWindow", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Apply all actions that are active within Resolution time after the current View Time"""
	SADeleteAddedExtra = ("SADeleteAddedExtra", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Clear Added and Extra Actions before running Identify Breakers"""
	SAEndTime = ("SAEndTime", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""End of time display window."""
	SAEvaluateManually = ("SAEvaluateManually", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Evaluate schedules at View Time only when specified by the user."""
	SAIdentifyBreakers = ("SAIdentifyBreakers", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Identify Breakers ignores any inactive Actions"""
	SAResolution = ("SAResolution", float, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Resolution of time display window"""
	SAResolutionUnits = ("SAResolutionUnits", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Units of the resolution of time display window"""
	SAStartTime = ("SAStartTime", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""Start of time display window."""
	SAUseActionFilter = ("SAUseActionFilter", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""When applying actions, use the filter currently applied to the Actions grid of the Scheduled Actions dialog"""
	SAUseNormal = ("SAUseNormal", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""When line elements that are referenced by a scheduled action are not being affected by that action, set them to their normal status."""
	SAViewTime = ("SAViewTime", str, FieldPriority.OPTIONAL | FieldPriority.EDITABLE)
	"""View point in time display window."""

	ObjectString = 'ScheduledActions_Options'


